"""Extract owner CSS/icons exactly, then scope and add accessibility integration rules."""
import re,json,pathlib,sys
root=pathlib.Path(__file__).resolve().parent.parent
source=pathlib.Path(sys.argv[1] if len(sys.argv)>1 else root/'docs/qa/evidence/voting-20260915/owner-design.md').read_text(encoding='utf-8')
styles=re.findall(r'<style>(.*?)</style>',source,re.S)
assert len(styles)==2
tokens="--guinda:#910022;--guinda-600:#7e0020;--guinda-700:#6a001b;--guinda-50:#fbeef1;--guinda-100:#f3d6de;--guinda-glow:#d11f3a;--guinda-coral:#e8364f;--grad-guinda:linear-gradient(150deg,#e8364f 0%,#c41230 42%,#910022 100%);--grad-guinda-soft:linear-gradient(145deg,#d11f3a,#910022);--ink:#14213d;--ink-2:#5a6378;--ink-3:#97a0b3;--surface:#fff;--surface-2:#eef1f6;--bg:#f2f3f5;--hairline:#e6eaf1;--neo-sm:0 6px 16px -8px rgba(20,33,61,.16),0 2px 5px rgba(20,33,61,.05);--neo-md:0 14px 30px -12px rgba(20,33,61,.2),0 4px 10px -2px rgba(20,33,61,.06);--neo-inset:inset 2px 2px 5px rgba(170,182,204,.3),inset -2px -2px 5px rgba(255,255,255,.9);--glow-guinda:0 10px 26px -6px rgba(209,31,58,.55),0 4px 10px -2px rgba(145,0,34,.4);--font:'Nunito',system-ui,sans-serif;--mono:'Spline Sans Mono',ui-monospace,monospace;"
out=[]
for scope,css in zip(['.voting-affiliate','.voting-admin'],styles):
 css=re.sub(r'(?<![.\w-])body\{[^}]*\}','',css)
 def scoped(m):
  s=m[1].strip()
  if s.startswith('@'): return s+'{'
  return ','.join(scope if x.strip()==':root' else scope+' '+x.strip() for x in s.split(','))+'{'
 css=re.sub(r'([^{}]+)\{',scoped,css)
 css=re.sub(r'font-size:([\d.]+)px',lambda m:'font-size:var(--text-'+m[1].replace('.','-')+','+m[1]+'px)',css)
 out.append(css)
out.append('.voting-ui{'+tokens+'font-family:var(--font);color:var(--ink);min-width:0}.voting-ui button,.voting-ui input,.voting-ui textarea{font-family:inherit}.voting-ui button{min-height:44px}.voting-ui button:disabled{opacity:.5;cursor:not-allowed}.voting-ui button:focus-visible,.voting-ui input:focus-visible,.voting-ui textarea:focus-visible{outline:3px solid var(--guinda);outline-offset:3px}.voting-ui svg{flex-shrink:0}.voting-ui .btn{height:auto;min-height:52px;padding:12px;white-space:normal}.voting-ui .icobtn,.voting-ui .back,.voting-ui .mail button{min-width:44px;min-height:44px}.voting-ui .tog{min-width:48px}.voting-ui .sheet{max-height:90dvh;overflow-y:auto}.voting-ui.backdrop{z-index:10000}.voting-ui .sheet{width:100%;max-width:560px}.voting-ui .row2{flex-wrap:wrap}.voting-ui .field{min-width:0;width:100%}.voting-ui .error{color:var(--guinda);padding:12px;line-height:1.5}.voting-admin{background:var(--bg);min-height:100%}.voting-admin .top{height:auto;min-height:76px}.voting-admin .scroll{overflow:visible}.voting-admin .bar{position:sticky;bottom:0;z-index:2}.voting-admin .card{flex-wrap:wrap}.voting-admin .qrow{flex-wrap:wrap}.voting-admin .tag{white-space:normal;height:auto;min-height:44px}.voting-admin .mode{text-align:left}.voting-admin .mail{overflow-wrap:anywhere;max-width:100%}.voting-admin .qrow b,.voting-admin h3,.voting-affiliate .qtext,.voting-affiliate .htitle{overflow-wrap:anywhere}.voting-affiliate .card+.card{margin-top:16px}.voting-affiliate .body{animation:voting-reveal .32s ease}.voting-affiliate .fill{transform:scaleX(1);animation:voting-bar .32s ease}.voting-ui .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@keyframes voting-reveal{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}@keyframes voting-bar{from{transform:scaleX(0)}to{transform:scaleX(1)}}@media(prefers-reduced-motion:reduce){.voting-ui *{animation:none!important;transition:none!important}}')
out.append('.voting-affiliate[data-voting-home]{margin-bottom:22px}.voting-ui .tog{height:44px;background:transparent;box-shadow:none}.voting-ui .tog:before{content:"";position:absolute;left:0;right:0;top:8px;height:28px;border-radius:999px;background:var(--surface-2)}.voting-ui .tog[aria-checked="true"]:before{background:var(--guinda);box-shadow:var(--glow-guinda)}.voting-ui .tog i{top:11px}.voting-ui .mail span{white-space:normal;overflow-wrap:anywhere}.voting-ui .bar{flex-wrap:wrap}.voting-ui .bar .btn{flex-basis:120px!important}.voting-ui .folio{overflow-wrap:anywhere;max-width:100%}')
out.append('.voting-affiliate .opts{flex-wrap:wrap}.voting-affiliate .opts .opt{flex:1 1 calc(85px * var(--text-scale,1));min-width:max-content}.voting-affiliate .opt span{white-space:nowrap;overflow-wrap:normal}')
icons=re.search(r'const ICO=(\{.*?\});',source,re.S)[1]
target=root/'app/voting-design.js'
target.write_text('/* Owner HTML contract: scoped CSS and original SVG paths. Generated by voting-prepare-design.py. */\nwindow.VotingDesign=Object.freeze({css:'+json.dumps('\n'.join(out),ensure_ascii=False)+',icons:'+icons+'});\n',encoding='utf-8')
print('Owner CSS and icons extracted')
